-- Synthetic cast records for storage tests (generated by FishingMastery/Synthetic.lua, the same
-- generator the developer stress command uses) and a writer for the client SavedVariables format.
local addon = require("spec.helpers.addon")

local Synthetic = addon.load({ "Synthetic.lua" }, nil, "FishingMastery").Synthetic

local M = {}

M.MAPS = Synthetic.MAPS
M.ITEMS = Synthetic.ITEMS
M.OUTCOMES = Synthetic.OUTCOMES

-- Returns count casts starting at server time start (oldest first).
function M.casts(count, start, seed)
    return Synthetic.Casts(count, start, seed)
end

-- Writes a table the way the Forever client writes SavedVariables: one value per line, hash keys
-- as ["key"] = value, array items bare, no indentation, CRLF line endings.
function M.write(name, value)
    local out = {}
    local function emit(v)
        local kind = type(v)
        if kind == "table" then
            out[#out + 1] = "{\r\n"
            local n = #v
            for i = 1, n do
                emit(v[i])
                out[#out + 1] = ",\r\n"
            end
            for key, child in pairs(v) do
                if not (type(key) == "number" and key >= 1 and key <= n and key % 1 == 0) then
                    out[#out + 1] = "["
                    out[#out + 1] = type(key) == "string" and string.format("%q", key)
                        or tostring(key)
                    out[#out + 1] = "] = "
                    emit(child)
                    out[#out + 1] = ",\r\n"
                end
            end
            out[#out + 1] = "}"
        elseif kind == "string" then
            out[#out + 1] = string.format("%q", v)
        else
            out[#out + 1] = tostring(v)
        end
    end
    out[#out + 1] = name .. " = "
    emit(value)
    out[#out + 1] = "\r\n"
    return table.concat(out)
end

return M
